//go:build s390x

package floats

// z/Architecture vector-facility kernels (z13 baseline, so no runtime gate, like
// sumVX): the float64 Add, Sub, Mul, Div, Sqrt of go-ndarray and the pairwise-sum
// block, generated by go-asmgen (lanes_s390x_gen.go) into lanes_s390x.s. Each
// element is one IEEE operation, no fused instruction: bit-identical to the
// scalar loops. The callers pass every slice already sliced to the common length.
//
//go:noescape
func addVX(dst, a, b *float64, n int)

//go:noescape
func subVX(dst, a, b *float64, n int)

//go:noescape
func mulVX(dst, a, b *float64, n int)

//go:noescape
func divVX(dst, a, b *float64, n int)

//go:noescape
func sqrtVX(dst, src *float64, n int)

// pwBlockVX is the 8 <= n <= 128 block of DOUBLE_pairwise_sum.
//
//go:noescape
func pwBlockVX(a *float64, n int) float64

func add(dst, a, b []float64) {
	if len(a) == 0 {
		return
	}
	addVX(&dst[0], &a[0], &b[0], len(a))
}

func sub(dst, a, b []float64) {
	if len(a) == 0 {
		return
	}
	subVX(&dst[0], &a[0], &b[0], len(a))
}

func mul(dst, a, b []float64) {
	if len(a) == 0 {
		return
	}
	mulVX(&dst[0], &a[0], &b[0], len(a))
}

func div(dst, a, b []float64) {
	if len(a) == 0 {
		return
	}
	divVX(&dst[0], &a[0], &b[0], len(a))
}

func sqrt(dst, src []float64) {
	if len(src) == 0 {
		return
	}
	sqrtVX(&dst[0], &src[0], len(src))
}

func clampScalar(dst, v []float64, lo, hi float64) { clampScalarRef(dst, v, lo, hi) }

func pairwiseBlock(a []float64) float64 { return pwBlockVX(&a[0], len(a)) }
